import hashlib,json,random,statistics
from pathlib import Path
p=Path(__file__).parent
load=lambda f:json.loads(Path(f).read_text())
def interval(xs):
 rng=random.Random(88)
 b=sorted(statistics.median(rng.choices(xs,k=len(xs))) for _ in range(10000))
 return {'median':statistics.median(xs),'bootstrap_95_interval':[b[249],b[9749]]}
summary={}
for name,original in load(p/'memory-summary.json').items():
 r=load(p/name/'runs.json')
 rows=[{**x,'mean_ms':statistics.mean(x['samples_ms']),'event_counts':{v['event']:float(v['counter-value']) for v in x['counters']}} for x in r['runs']]
 pairs=[{x['label']:x for x in rows if x['pair']==i} for i in range(r['pair_count'])]
 counters={}
 for event in rows[0]['event_counts']:
  a=[pair['before']['event_counts'][event] for pair in pairs]
  b=[pair['after']['event_counts'][event] for pair in pairs]
  counters[event]={'before_median_per_execution':statistics.median(a)/r['samples'],'after_median_per_execution':statistics.median(b)/r['samples'],'paired_absolute_change_per_execution':interval([(y-x)/r['samples'] for x,y in zip(a,b)]),'paired_percentage_change':interval([100*(y/x-1) for x,y in zip(a,b)]) if all(a) else None}
 means=[100*(pair['after']['mean_ms']/pair['before']['mean_ms']-1) for pair in pairs]
 correlations={}
 for variant in sorted(set(x['variant'] for x in rows)):
  group=[x for x in rows if x['variant']==variant]
  correlations[variant]={event:statistics.correlation([x['event_counts'][event] for x in group],[x['mean_ms'] for x in group]) for event in ['ls_dmnd_fills_from_sys.local_ccx:u','ls_dmnd_fills_from_sys.dram_io_near:u']}
 summary[name]={'pairs':r['pair_count'],'scenario':r['scenario'],'median_time':{'median_paired_change_pct':original['median_paired_change_pct'],'bootstrap_95_interval':original['paired_median_bootstrap_95_percentile_interval']},'mean_time':interval(means),'counters':counters,'within_variant_counter_mean_time_pearson':correlations}
(p/'analysis.json').write_text(json.dumps(summary,indent=2)+'\n')
for name,row in summary.items():
 print(row['scenario'],'time',row['median_time'],'mean',row['mean_time'])
 for event in ['instructions:u','cycles:u','ls_dmnd_fills_from_sys.local_ccx:u','ls_dmnd_fills_from_sys.dram_io_near:u']:
  print(event,row['counters'][event])
 print('correlations',row['within_variant_counter_mean_time_pearson'])
